]={url:"https://static-public-media.higgsfield.ai/ai-reels-presets/3e502c1c-fe17-4d94-b0e1-10cd79709794.mp4",compressed_url:"https://static-public-media.higgsfield.ai/ai-reels-presets/2dfd9fdb-4c03-4fba-8a77-0ea9e16cc2ce.mp4",width:1080,height:1920,media_id:"0b93bada-0f67-4eb2-801e-aa6eac91cf73",duration_seconds:null,thumbnail_url:"https://static-public-media.higgsfield.ai/ai-reels-presets/fd2a36ff-a8ad-45bb-a436-25a303fe7fae.webp"},views:91305,likes:5757,comments:141,recreates:217,source_url:"https://www.instagram.com/reel/Dc9eLjnt223/",source_platform:"instagram",author_handle:"mariadonofrio_",hashtags:$R[1200]=["moneyhabits","personalfinance","savingmoney"],own_recording:!1,instructions:void 0,own_videos:$R[1201]=[],script:"Every money guru online had a secret to sell me. A course, a signal group, a rented sports car in the background. And I was still broke by the twentieth of every month.\n\nThen it clicked. The only one getting rich from those courses was the person selling them.\n\nSo now I keep my money on four quiet pillars: cushion, autopilot, boring, and patience.\n\nCushion: three months of bills, untouched. Autopilot: savings leave on payday. Boring: broad, dull funds, no hot tips. Patience: let the years work.\n\nTogether, money finally got quiet. I check it once a month and sleep just fine.\n\nSo I put all four on one page, and it beat every course I almost bought. No secret made me calm. Boring habits did.",quality:"1080p",duration_seconds:50.084},$R[1202]={id:"6850c551-da96-4a99-b317-20002e5add29",slug:"new-27-10-4-starting-a-clothing-brand",source:"higgsfield",title:"Starting a Clothing Brand",description:"An honest clothing brand startup story with bold captions and graphic overlays.",category:"style-transfer",thumbnail_media:$R[1203]={url:"https://static-public-media.higgsfield.ai/ai-reels-presets/f018fb2f-5368-4f14-bd4b-21155684ec40.jpg"},video_media:$R[1204]={url:"https://static-public-media.higgsfield.ai/ai-reels-presets/7c1ee4f3-e5af-4a27-a8a1