edia.higgsfield.ai/ai-reels-presets/110fe1cb-a6b2-489d-8399-99436e2252e3.webp"},character_media:$R[1212]={url:"https://static-public-media.higgsfield.ai/ai-reels-presets/cb42d7bd-4b4b-49e5-9be6-d9e2e2661614.png",width:864,height:1152},generated_video_media:$R[1213]={url:"https://static-public-media.higgsfield.ai/ai-reels-presets/9d3a368d-6681-4157-897b-a4bfd7dd2a7f.mp4",compressed_url:"https://static-public-media.higgsfield.ai/ai-reels-presets/7427d6be-b0eb-41f6-ae97-d08bcf12d568.mp4",width:1080,height:1920,media_id:"1da61492-47f7-4a7c-be9d-45023cb71ece",duration_seconds:null,thumbnail_url:"https://static-public-media.higgsfield.ai/ai-reels-presets/542a9b20-78f5-40fb-a70b-7f35fc04b39d.webp"},views:453298,likes:39205,comments:18899,recreates:299,source_url:"https://www.instagram.com/reels/DBZJRlZoD7R/",source_platform:"instagram",author_handle:"wordswithruss",hashtags:$R[1214]=["partyplanning","eventtips"],own_recording:!1,instructions:void 0,own_videos:$R[1215]=[],script:"This is your reminder that your party is not boring. It probably just needs a little direction to feel unforgettable. Five lessons of throwing an unforgettable party.\n\nLesson one. I spent eight years planning weddings and parties people still talk about, and I learned it's never the budget that makes the night. It's the parts nobody plans.\n\nSo I split it into five: the music, the light, the timing, the food, and the details. Details are my favorite, and honestly the most overlooked. I'll talk about that another time. Each one needs the same attention.\n\nWithout music, people won't dance, no matter how good the playlist looks on paper. Without light, the room has no mood. Without timing, the energy drops halfway through the night. And the food? Hungry guests leave early.\n\nI put all of it into one guide for your next event. Comment party below, and I'll send it to you. And one more thing: it's completely free.",quality:"1080p",duration_seconds:45.583659},$R[1216]={id:"f2f8f72f-becb-460a-bc3f-d