55,height:1152},generated_video_media:$R[1269]={url:"https://static-public-media.higgsfield.ai/ai-reels-presets/a1091991-7bdb-4df5-855e-14004950f9dc.mp4",compressed_url:"https://static-public-media.higgsfield.ai/ai-reels-presets/df511172-8abe-40ac-ae2d-813c74ef64e4.mp4",width:1080,height:1920,media_id:"e3dd68e0-5425-4e8a-aa93-6c26d87cf594",duration_seconds:null,thumbnail_url:"https://static-public-media.higgsfield.ai/ai-reels-presets/528efe16-53f1-4f88-82a5-ba9970f78f0f.webp"},views:2072065,likes:216199,comments:328,recreates:161,source_url:"https://www.instagram.com/reel/DeUmh5PtNkL/",source_platform:"instagram",author_handle:"jackkgriffith",hashtags:$R[1270]=["familytime","parents"],own_recording:!1,instructions:void 0,own_videos:$R[1271]=[],script:"You'll see your parents maybe 200 more days, all right, not exactly, but stay with me. On average, they've got something like 30 years left, which sounds like a lot, sounds like plenty, but then you start subtracting. You moved out, so it's not every day anymore.\n\nWork takes most of your weekends, then trips with friends, then flights you keep putting off, calls you skip. I'll come next month, which for most people turns into twice a year, every year, forever, and you're down to around 200 days together that are actually left.\n\nThat's the real number. That's what you're working with. And the part that gets me is that nobody's taking those days from you. You're giving them away one next month at a time without noticing. 200 days with them and you just spent a minute of one watching this.\n\nGo call them.",quality:"1080p",duration_seconds:47},$R[1272]={id:"46e50abb-5f83-4f9a-99d8-a2a8a602ad48",slug:"new-27-10-91-toykind-sunday",source:"higgsfield",title:"Toykind Sunday",description:"An everyday city vlog transformed into a miniature toy world.",category:"style-transfer",thumbnail_media:$R[1273]={url:"https://static-public-media.higgsfield.ai/ai-reels-presets/ccf8b5ca-fb49-4ecb-a48a-d3a31dea872d.jpg"},video_media:$R[1